-- ============================================================
-- Semilla del catálogo de maquinaria (tabla `maquinaria`) y de la
-- ubicación inicial de las unidades que ya tenían datos en el
-- inventario de tractores (INVENTARIO_TRACTORES.xlsx).
--
-- Es seguro volver a correr este script: usa
-- "ON DUPLICATE KEY UPDATE" en todo, así que no duplica nada si ya
-- se había corrido antes.
--
-- Uso:
--   mysql -u root -p reporte_fallas < db\seed_maquinaria.sql
-- ============================================================

USE reporte_fallas;

-- ------------------------------------------------------------
-- 1) Catálogo completo (todas las unidades). Las que además
--    aparecían en el inventario de tractores llevan ya su
--    departamento, marca, modelo, año, color, serie y tipo; el
--    resto queda con esos campos en NULL hasta que se editen
--    desde la pestaña "Maquinaria" del Panel.
-- ------------------------------------------------------------

-- ------------------------------------------------------------
-- 2) Ubicación inicial: para las unidades que ya sabíamos dónde
--    estaban (según el inventario de tractores), se registra un
--    movimiento ya "confirmado" con folio SEED-##### (para que
--    nunca choque con los folios reales MOV-##### que genera la
--    app). Si se vuelve a correr este script, no duplica: cada
--    unidad solo lleva UN registro semilla (se identifica por su
--    folio, que es fijo por unidad).
-- ------------------------------------------------------------

